// 1) Lit l'entrée et prépare l'appel Gemini de reformulation de la requête
const input = $input.first().json;
const body = input.body || input;

// message (sous-workflow / webhook) ou original_message (item complet de l'orchestrateur)
const userMessage = (body.message || body.original_message || '').toString().trim();
const sessionId = body.session_id || 'unknown';
let userContext = body.user_context || {};
if (typeof userContext === 'string') {
  try { userContext = JSON.parse(userContext); } catch (e) { userContext = {}; }
}

const rewritePrompt = `Tu transformes la question d'un client sur le marché immobilier marocain en requête de recherche web en français.
Réponds UNIQUEMENT avec un objet JSON, sans texte autour :
{"query": "", "quartier": "", "ville": "", "type_bien": "", "langue": ""}

Règles :
- query : au format "prix m2 <type_bien> <quartier> <ville>" (sans quartier ou sans ville s'ils sont absents du message).
- Corrige seulement l'orthographe et les abréviations courantes (casa -> Casablanca, maarif -> Maarif). N'ajoute aucun lieu absent du message.
- type_bien : appartement, villa, maison, terrain, bureau ou local. Par défaut : appartement.
- langue : "darija_latin" (darija en lettres latines), "darija_arabe" (darija en lettres arabes), "ar" (arabe standard), "fr" ou "en".
- Si une information manque, mets "".

Message du client : "${userMessage.replace(/"/g, "'")}"`;

return [{
  json: {
    user_message: userMessage,
    session_id: sessionId,
    user_context: userContext,
    rewrite_request_body: {
      contents: [{ role: "user", parts: [{ text: rewritePrompt }] }],
      generationConfig: { temperature: 0, responseMimeType: "application/json" }
    }
  }
}];

// 2) Lit la reformulation (avec repli sur le message brut) et prépare Tavily
const prep = $('Préparer recherche').first().json;
const g = $input.first().json;

let parsed = null;
let rewriteError = null;
try {
  const text = (g.candidates[0].content.parts || []).map(p => p.text || '').join('');
  parsed = JSON.parse(text.replace(/```json|```/g, '').trim());
} catch (e) {
  rewriteError = g.error ? (g.error.message || 'gemini_error') : 'parse_error';
}

const str = (v) => (typeof v === 'string' ? v.trim() : '');
const rewritten = str(parsed && parsed.query);
const query = rewritten || prep.user_message;

// Sites immobiliers marocains autorisés comme sources
const DOMAINES = ["mubawab.ma", "yakeey.com", "agenz.ma", "sarouty.ma", "avito.ma"];

return [{
  json: {
    user_message: prep.user_message,
    session_id: prep.session_id,
    search_query: query.slice(0, 400),
    query_rewritten: rewritten !== '',
    rewrite_error: rewriteError,
    quartier: str(parsed && parsed.quartier),
    ville: str(parsed && parsed.ville),
    type_bien: str(parsed && parsed.type_bien) || 'appartement',
    langue: str(parsed && parsed.langue),
    tavily_body: {
      query: query.slice(0, 400),
      search_depth: "advanced",
      max_results: 5,
      include_answer: false,
      include_domains: DOMAINES
    }
  }
}];

// 3) Construit le prompt de synthèse à partir des résultats Tavily numérotés
const prep = $('Préparer Tavily').first().json;
const tav = $input.first().json;

const results = Array.isArray(tav.results) ? tav.results : [];
const tavilyError = tav.error ? (tav.error.message || JSON.stringify(tav.error)) : null;

// new URL() n'est pas disponible dans le sandbox n8n : extraction par regex
const getDomain = (url) => {
  const m = (url || '').match(/^https?:\/\/(?:www\.)?([^\/?#]+)/i);
  return m ? m[1].toLowerCase() : '';
};

const sources = results.map((r, i) => ({
  n: i + 1,
  title: r.title || '',
  url: r.url || '',
  domain: getDomain(r.url),
  content: (r.content || '').replace(/\s+/g, ' ').slice(0, 1500)
}));

const today = new Date().toISOString().slice(0, 10);

// Les noms de sites ne sont pas donnés au modèle (seulement titre + contenu)
const sourcesText = sources.length > 0
  ? sources.map(s => `[${s.n}] ${s.title}\n${s.content}`).join('\n\n')
  : 'AUCUNE SOURCE TROUVÉE.';

const LANGUES = {
  darija_latin: "en darija marocaine écrite en lettres latines (comme le client)",
  darija_arabe: "en darija marocaine écrite en lettres arabes",
  ar: "en arabe standard",
  fr: "en français",
  en: "en anglais"
};
const consigneLangue = LANGUES[prep.langue] || "dans la même langue que le message du client";

const demande = `Quartier demandé : ${prep.quartier || 'non précisé'} | Ville : ${prep.ville || 'non précisée'} | Type de bien : ${prep.type_bien}`;

const systemPrompt = `Tu es le conseiller marché immobilier de Darimmo, une plateforme marocaine d'annonces immobilières.
Tu réponds UNIQUEMENT à partir des sources numérotées ci-dessous (résultats d'une recherche web effectuée le ${today}). Tu ne connais aucun prix par toi-même.

Objectif : donner au client le prix au m² demandé, en une réponse très courte : prix moyen au m² et, si la source la donne, la fourchette (minimum - maximum). Rien d'autre.

Règles strictes :
1. Utilise uniquement les référentiels de prix au m² (pages de type "prix au m²", "référentiel", "carte des prix"). N'utilise PAS les annonces individuelles, ni des chiffres anciens datés d'années passées, et ne cite aucun exemple d'annonce.
2. Chaque chiffre que tu donnes doit apparaître tel quel dans une source, suivi de son numéro entre crochets, par exemple [2]. N'invente aucun chiffre, ne calcule rien, ne fais pas de moyenne.
3. Le type de bien doit correspondre à la demande. Ne mélange jamais les chiffres des appartements et des villas.
4. Format fréquent des référentiels : "Appartements 11 012 DH/m² Prix m2 moyen 8 607 DH/m² 12 664 DH/m²" signifie : prix moyen 11 012 DH/m², fourchette de 8 607 à 12 664 DH/m². Si le texte ne suit pas clairement ce format, ou si tu n'es pas sûr du sens d'un chiffre (moyenne ou borne, appartement ou villa, vente ou location), ne l'utilise pas.
5. Quartier : utilise en priorité un référentiel du quartier demandé. S'il n'y en a pas, mais qu'il existe des référentiels de sous-quartiers clairement rattachés au quartier demandé (titre du type "Palmier (Maarif)"), donne au maximum 2 sous-quartiers, en précisant pour chacun qu'il s'agit d'une partie du quartier, chacun avec ses propres chiffres. N'utilise jamais un autre quartier non rattaché, ni un chiffre de la ville entière pour un quartier.
6. Si aucun référentiel fiable ne convient, dis simplement (dans la langue demandée) que tu n'as pas trouvé d'information fiable sur le prix au m² de ce quartier, sans aucun chiffre.
7. Date : si la source utilisée indique une date de mise à jour, mentionne-la ; sinon indique que ce sont des estimations consultées le ${today}. N'invente aucune date.
8. Ne mentionne aucun nom de site, de plateforme ou d'agence, et aucune URL. Parle de "référentiels de prix du marché".
9. Si tu donnes un chiffre, termine par une phrase courte : le prix est indicatif et dépend de la surface, de l'étage et de l'état du bien.
10. Si la question ne concerne pas les prix ou le marché immobilier, réponds brièvement que tu traites les questions de prix et de marché immobilier.
11. LANGUE : réponds ${consigneLangue}. Toute la réponse, y compris la phrase de la règle 6, doit être dans cette langue.
12. Pas de Markdown (pas de ** ni de #, pas de liste). 70 mots maximum.`;

const prompt = `${systemPrompt}\n\nDEMANDE : ${demande}\n\nSOURCES :\n${sourcesText}\n\nMessage du client : "${prep.user_message}"`;

return [{
  json: {
    user_message: prep.user_message,
    session_id: prep.session_id,
    search_query: prep.search_query,
    query_rewritten: prep.query_rewritten,
    rewrite_error: prep.rewrite_error,
    langue: prep.langue,
    today,
    sources,
    tavily_error: tavilyError,
    gemini_request_body: {
      contents: [{ role: "user", parts: [{ text: prompt }] }],
      generationConfig: { temperature: 0.2 }
    }
  }
}];

// 4) Réponse courte pour le client (sans liens ni noms de sites)
// Les sources citées sont gardées uniquement dans metadata (non affichées)
const prep = $('Construire prompt marché').first().json;
const g = $input.first().json;

let rawReply = '';
try {
  rawReply = (g.candidates[0].content.parts || []).map(p => p.text || '').join('').trim();
} catch (e) {
  rawReply = '';
}
const geminiError = g.error ? (g.error.message || JSON.stringify(g.error)) : null;

// Sources citées ([1], [2], [1, 3]...) -> metadata uniquement
const sources = prep.sources || [];
const citedNumbers = new Set();
for (const m of rawReply.matchAll(/\[(\d+(?:\s*,\s*\d+)*)\]/g)) {
  m[1].split(',').forEach(x => citedNumbers.add(parseInt(x.trim(), 10)));
}
const citedSources = sources
  .filter(s => citedNumbers.has(s.n))
  .map(s => ({ n: s.n, title: s.title, url: s.url, domain: s.domain }));

// Nettoyage du texte destiné au client
let reply = rawReply
  .replace(/\s*\[\d+(?:\s*,\s*\d+)*\]/g, '')          // citations [n]
  .replace(/\s*\(\s*https?:\/\/[^\s)]*\s*\)/g, '')    // URL entre parenthèses
  .replace(/https?:\/\/[^\s)]+/g, '')                 // URL éventuelles
  .replace(/\*\*|__|#/g, '');                          // Markdown

// Filet de sécurité : noms de sites concurrents
const SITE_NAMES = /\b(yakeey|agenz|mubawab|sarouty|avito)(\.(ma|com))?\b/gi;
const siteNameLeak = SITE_NAMES.test(reply);
reply = reply.replace(SITE_NAMES, 'un référentiel de prix');

reply = reply.replace(/[ \t]+([.,;:!?])/g, '$1').replace(/[ \t]{2,}/g, ' ').trim();

if (!reply) {
  const FALLBACK = {
    darija_latin: "Sm7 lina, ma9dernach njawbo 3la had s-su2al daba. 3awed jarreb mn b3d.",
    en: "Sorry, I can't answer this market question right now. Please try again later."
  };
  reply = FALLBACK[prep.langue] || "Désolé, je ne peux pas répondre à cette question sur le marché pour le moment. Veuillez réessayer plus tard.";
}

return [{
  json: {
    reply,
    session_id: prep.session_id,
    recommended_annonce_ids: [],
    intent: "market_advice",
    metadata: {
      agent_used: "market_advice_agent",
      tool_calls_count: 1,
      llm_calls_count: 2,
      search_query: prep.search_query,
      query_rewritten: prep.query_rewritten,
      langue: prep.langue,
      sources_count: sources.length,
      cited_sources_count: citedSources.length,
      cited_sources: citedSources,
      site_name_leak: siteNameLeak,
      rewrite_error: prep.rewrite_error,
      tavily_error: prep.tavily_error,
      gemini_error: geminiError
    }
  }
}];
